const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '细胞壁' },
      { kind: 'text', payload: '细胞核' },
      { kind: 'text', payload: '液泡' }
    ];
  },
  render: function (input, metrics) {
    var W = (input.viewport && input.viewport.widthDu) || 800;
    var H = (input.viewport && input.viewport.heightDu) || 600;
    var minD = Math.min(W, H);
    function ellipse(cx, cy, rx, ry) {
      var k = 0.5522847498;
      var ox = rx * k;
      var oy = ry * k;
      return [
        ['M', cx + rx, cy],
        ['C', cx + rx, cy + oy, cx + ox, cy + ry, cx, cy + ry],
        ['C', cx - ox, cy + ry, cx - rx, cy + oy, cx - rx, cy],
        ['C', cx - rx, cy - oy, cx - ox, cy - ry, cx, cy - ry],
        ['C', cx + ox, cy - ry, cx + rx, cy - oy, cx + rx, cy],
        ['Z']
      ];
    }
    function smoothClosed(pts) {
      var n = pts.length;
      var cmds = [['M', pts[0][0], pts[0][1]]];
      for (var i = 0; i < n; i++) {
        var p0 = pts[(i - 1 + n) % n];
        var p1 = pts[i];
        var p2 = pts[(i + 1) % n];
        var p3 = pts[(i + 2) % n];
        cmds.push(['C', p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6, p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6, p2[0], p2[1]]);
      }
      cmds.push(['Z']);
      return cmds;
    }
    function segment(a, b) {
      return [['M', a[0], a[1]], ['L', b[0], b[1]]];
    }
    var rel = [[0.16, 0.30], [0.30, 0.14], [0.55, 0.11], [0.78, 0.21], [0.87, 0.42], [0.85, 0.66], [0.70, 0.86], [0.44, 0.89], [0.22, 0.79], [0.12, 0.56]];
    var pts = rel.map(function (p) { return [p[0] * W, p[1] * H]; });
    var sx = 0;
    var sy = 0;
    for (var j = 0; j < pts.length; j++) {
      sx += pts[j][0];
      sy += pts[j][1];
    }
    var gx = sx / pts.length;
    var gy = sy / pts.length;
    var inner = pts.map(function (p) { return [gx + (p[0] - gx) * 0.945, gy + (p[1] - gy) * 0.945]; });
    var wallW = Math.max(5, minD * 0.024);
    var vacCx = 0.55 * W;
    var vacCy = 0.52 * H;
    var vacRx = 0.225 * W;
    var vacRy = 0.205 * H;
    var nucCx = 0.27 * W;
    var nucCy = 0.64 * H;
    var nucR = minD * 0.075;
    var nolCx = nucCx + nucR * 0.22;
    var nolCy = nucCy - nucR * 0.20;
    var nolR = nucR * 0.30;
    var wallLead = [[0.135 * W, 0.095 * H], [0.245 * W, 0.165 * H]];
    var vacLead = [[0.795 * W, 0.095 * H], [vacCx + 0.5 * (vacRx + 4), vacCy - 0.866 * (vacRy + 4)]];
    var nucLead = [[0.145 * W, 0.885 * H], [nucCx - 0.866 * (nucR + 4), nucCy + 0.5 * (nucR + 4)]];
    var dotR = Math.max(2.5, minD * 0.006);
    var paths = [
      { id: 'wall', commands: smoothClosed(pts) },
      { id: 'inner', commands: smoothClosed(inner) },
      { id: 'vacRim', commands: ellipse(vacCx, vacCy, vacRx + 4, vacRy + 4) },
      { id: 'vacBody', commands: ellipse(vacCx, vacCy, vacRx, vacRy) },
      { id: 'nucRim', commands: ellipse(nucCx, nucCy, nucR + 4, nucR + 4) },
      { id: 'nucBody', commands: ellipse(nucCx, nucCy, nucR, nucR) },
      { id: 'nucleolus', commands: ellipse(nolCx, nolCy, nolR, nolR) },
      { id: 'leadWall', commands: segment(wallLead[0], wallLead[1]) },
      { id: 'leadVacuole', commands: segment(vacLead[0], vacLead[1]) },
      { id: 'leadNucleus', commands: segment(nucLead[0], nucLead[1]) },
      { id: 'dotWall', commands: visualSdk.circle(wallLead[1][0], wallLead[1][1], dotR) },
      { id: 'dotVacuole', commands: visualSdk.circle(vacLead[1][0], vacLead[1][1], dotR) },
      { id: 'dotNucleus', commands: visualSdk.circle(nucLead[1][0], nucLead[1][1], dotR) }
    ];
    return {
      schemaVersion: 1,
      sceneId: 'plant-cell-schematic',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: [
        { type: 'path', pathId: 'wall', fill: '#93C271', stroke: { width: wallW, join: 'round' } },
        { type: 'path', pathId: 'inner', fill: '#F7FBF0' },
        { type: 'path', pathId: 'vacRim', fill: '#9CC8DC' },
        { type: 'path', pathId: 'vacBody', fill: '#E3F2F9' },
        { type: 'path', pathId: 'nucRim', fill: '#C79BCB' },
        { type: 'path', pathId: 'nucBody', fill: '#F3E2F3' },
        { type: 'path', pathId: 'nucleolus', fill: '#B183B5' },
        { type: 'path', pathId: 'leadWall', fill: '#3E5A34', stroke: { width: 1.8, cap: 'round' } },
        { type: 'path', pathId: 'leadVacuole', fill: '#3E5A34', stroke: { width: 1.8, cap: 'round' } },
        { type: 'path', pathId: 'leadNucleus', fill: '#3E5A34', stroke: { width: 1.8, cap: 'round' } },
        { type: 'path', pathId: 'dotWall', fill: '#3E5A34' },
        { type: 'path', pathId: 'dotVacuole', fill: '#3E5A34' },
        { type: 'path', pathId: 'dotNucleus', fill: '#3E5A34' },
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: 0.115 * W, y: 0.065 * H }, hAlign: 'center', vAlign: 'middle', color: '#33502C' },
        { type: 'label', contentId: metrics[1].contentId, anchor: { x: 0.10 * W, y: 0.905 * H }, hAlign: 'center', vAlign: 'middle', color: '#33502C' },
        { type: 'label', contentId: metrics[2].contentId, anchor: { x: 0.82 * W, y: 0.065 * H }, hAlign: 'center', vAlign: 'middle', color: '#33502C' }
      ] }
    };
  }
};
